parameters.jsCode:
let text = "";
let knowledgeBase = $('Aggregate').first().json.knowldge_base;
knowledgeBase.push({
  title: $input.first().json.title,
  text: $input.first().json.text
})
for (const item of knowledgeBase) {
  text += item.title+'\n\r'+item.text+'\n\r---\n\r'
}

return {text:text}

